import { Button } from "./Button"
import axios from "axios"
import {useState, useContext} from "react"
import { UserContext } from "./App"



export function Tasks(props){
    const [task, setTask] = useState(props.taskName)
    const [due_date, setDueDate] = useState(props.dueDate)

    return(
        <>
            <div>
                <p>{props.taskName}</p>
                <p>{props.dueDate}</p>
                <Button text="Done"></Button>
                <br></br>
            </div>
        </>
    )
    function removeTask(){
        const deleteRes = axios.delete("http://localhost:8081/deleteTasks")
    }
}
